window.MG_LAZY_DATA["data/lazy/courses/b401-4303c9dd3c30456c.json"]={sha256:"4303c9dd3c30456c6cba5f44089f57f3ec8509158b8f9a7cdc1008966896afe6",value:{"id":"b401","category":"environment","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"languageCoverage":["zh-TW","en"],"sourceIds":["v6-newater-process","v6-newater-quality","v6-newater-parameters","v6-video-P7UDE2cISPQ"],"stages":[{"id":"b401-stage01","order":1,"steps":[{"id":"b401-v6-01","sequence":1,"order":1,"sourceIds":["v6-newater-process"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":[],"title":"閉合回用水流程","titleEn":"Close the reclaimed-water loop","objective":"區分已處理用水、再生水與最終使用。","objectiveEn":"Distinguish treated used water, reclaimed product and final use.","instruction":"畫出已處理用水→MF/UF→RO→UV的概念流程，另分工業專管與水庫→淨水場→自來水兩條用途支路。標示這是一般教學路線，MBR等實廠配置可能不同。","instructionEn":"Draw treated used water to MF/UF, RO and UV. Add industrial dedicated supply and reservoir-to-waterworks-to-taps branches. Label this a general teaching route; actual configurations such as MBR may differ.","observation":"確認原污水並未直接接入再生水產品端，間接飲用支路也沒有略過淨水場。","observationEn":"Confirm raw sewage is not connected directly to product and the indirect-potable branch does not omit waterworks.","failure":"把NEWater等同未處理污水，或把間接飲用畫成直接供水。","failureEn":"Equating NEWater with untreated sewage or drawing indirect reuse as direct tap supply.","check":"每個水質邊界都有名稱，兩條使用支路可獨立追蹤。","checkEn":"Name each water-quality boundary and make both use branches traceable.","knowledge":[{"id":"b401-v6-01-k1","title":"水質邊界","titleEn":"Water-quality boundaries","text":"已處理用水仍需後續純化；不同水流名稱代表不同處理狀態。","textEn":"Treated used water still requires further purification; stream names indicate different treatment states."},{"id":"b401-v6-01-k2","title":"用途路徑","titleEn":"Use pathways","text":"工業供水與間接飲用回用有不同的下游系統介面。","textEn":"Industrial supply and indirect potable reuse connect to different downstream systems."}],"quiz":{"options":["淨水場再處理後才供應自來水","直接跳過任何後續處理","改由工業專管自動變成家戶管線"],"optionsEn":["Waterworks treatment before tap-water supply","Bypass all subsequent treatment","Automatically turn an industrial main into household supply"],"answer":0,"question":"在PUB描述的間接飲用路徑中，水庫之後還有什麼？","questionEn":"In PUB’s described indirect-potable route, what follows the reservoir?","explanation":"「間接」包含水庫混合與後續淨水處理，不能刪除。","explanationEn":"Indirect reuse includes reservoir blending and subsequent waterworks treatment."}},{"id":"b401-v6-02","sequence":2,"order":2,"sourceIds":["v6-newater-process","v6-newater-quality"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-01"],"title":"建立進流水的資料邊界","titleEn":"Define the feedwater data boundary","objective":"把上游處理狀態與下游膜系統需求對齊。","objectiveEn":"Match upstream treatment status with downstream membrane evidence needs.","instruction":"自設一張進流水紀錄表，分別列流量、混濁、溶解物及微生物資料欄。對缺少數據的欄位保留未知，說明它可能影響哪一道後續屏障。","instructionEn":"Create a feedwater-record template for flow, turbidity, dissolved substances and microbiological evidence. Keep missing fields unknown and identify the downstream barrier each may affect.","observation":"比較水看起來透明與已取得化學或微生物證據的差別。","observationEn":"Distinguish visual clarity from chemical or microbiological evidence.","failure":"以肉眼清澈取代進流水品質與處理狀態確認。","failureEn":"Substituting visual clarity for feed-quality and treatment-status verification.","check":"至少四個資料欄各連到一項後續功能或驗證需求。","checkEn":"Link at least four fields to a downstream function or verification need.","knowledge":[{"id":"b401-v6-02-k1","title":"污染物類別","titleEn":"Contaminant classes","text":"粒子、溶解成分與微生物需要不同的量測與處理觀點。","textEn":"Particles, dissolved constituents and microorganisms require different measurement and treatment perspectives."},{"id":"b401-v6-02-k2","title":"上游依賴","titleEn":"Upstream dependency","text":"後段設備的表現受進流水條件影響，不能只看設備名稱。","textEn":"Downstream performance depends on feed conditions, not just equipment names."}],"quiz":{"options":["透明等於所有溶解物已去除","外觀已觀察，化學條件仍未知","可用出水流量代替化學資料"],"optionsEn":["Clarity means all dissolved substances are removed","Appearance observed; chemical conditions unknown","Product flow can replace chemical data"],"answer":1,"question":"進流水透明但化學資料缺漏，最適合的記錄是什麼？","questionEn":"Feedwater looks clear but chemical data is missing. What should be recorded?","explanation":"外觀只能描述有限性質，不能補出未量測的污染物資料。","explanationEn":"Appearance describes limited properties and cannot supply missing contaminant measurements."}},{"id":"b401-v6-03","sequence":3,"order":3,"sourceIds":["v6-newater-process","v6-newater-parameters"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-02"],"title":"分辨MF/UF與RO的任務","titleEn":"Distinguish MF/UF and RO roles","objective":"用污染物類型理解不同膜屏障的互補。","objectiveEn":"Use contaminant classes to understand complementary membrane barriers.","instruction":"畫三類符號代表粒子、微生物與溶解離子，將MF/UF與RO畫成不同功能方塊。用「可能被截留／仍需下段處理／需量測確認」標記，不填通用百分之百去除承諾。","instructionEn":"Represent particles, microorganisms and dissolved ions with symbols, and draw separate MF/UF and RO blocks. Label retained, requiring downstream treatment and needing measurement without universal 100-percent removal claims.","observation":"注意前段粒子控制可改善後段條件，但不是所有溶解物的證明。","observationEn":"Particle control upstream can improve downstream conditions without proving removal of every dissolved constituent.","failure":"把所有膜都當成同一種細篩，認為第一道即可取代全部後段。","failureEn":"Treating all membranes as the same fine sieve and assuming the first replaces every later barrier.","check":"三類符號均有去向與未確認項，且MF/UF和RO功能可區分。","checkEn":"Give each symbol a destination and unresolved point, with distinguishable MF/UF and RO roles.","knowledge":[{"id":"b401-v6-03-k1","title":"互補屏障","titleEn":"Complementary barriers","text":"不同單元針對不同性質的污染物，串接可處理不同風險。","textEn":"Different units address different contaminant properties; a train combines complementary functions."},{"id":"b401-v6-03-k2","title":"簡化限制","titleEn":"Limits of simplification","text":"圖上符號只教分類，不代表特定膜在所有條件下的截留率。","textEn":"Diagram symbols teach categories, not rejection rates of a particular membrane under all conditions."}],"quiz":{"options":["所有溶解鹽類都已移除","後段RO和UV永遠可以取消","該量測條件下粒子相關指標較低"],"optionsEn":["All dissolved salts have been removed","RO and UV can always be omitted","A low particle-related indicator under those measurement conditions"],"answer":2,"question":"MF/UF出水低濁度能單獨證明什麼？","questionEn":"What does low MF/UF product turbidity establish on its own?","explanation":"低濁度不是所有化學與微生物條件的完整證明。","explanationEn":"Low turbidity is not complete evidence of every chemical and microbiological condition."}},{"id":"b401-v6-04","sequence":4,"order":4,"sourceIds":["v6-newater-process","v6-newater-quality"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-03"],"title":"檢查第一道膜屏障的完整性","titleEn":"Review first-barrier integrity evidence","objective":"辨認產水量與膜屏障完整性不同。","objectiveEn":"Distinguish water production from membrane-barrier integrity.","instruction":"自繪膜模組及密封介面，標出穿膜與繞過密封的兩種可能路徑。建立完整性證據、出水觀察與設備狀態三欄，所有數據留作自設教學示例。","instructionEn":"Sketch a membrane module and seals, marking passage through the membrane and possible seal bypass. Create integrity-evidence, product-observation and equipment-state columns using only labeled example data.","observation":"觀察出水量正常是否仍可能有旁通或局部缺陷。","observationEn":"Consider whether normal product flow can coexist with bypass or a local defect.","failure":"以流量正常或馬達運轉，替代屏障完整性證據。","failureEn":"Using normal flow or a running motor as proof of barrier integrity.","check":"列出兩種缺陷假說及能區分它們的觀察，不能只寫「正常」。","checkEn":"List two defect hypotheses and observations distinguishing them rather than simply writing normal.","knowledge":[{"id":"b401-v6-04-k1","title":"完整性與通量","titleEn":"Integrity versus throughput","text":"流得過去說明有產水，不等於水只經過預期的屏障。","textEn":"Flow establishes production, not that all water passed through the intended barrier."},{"id":"b401-v6-04-k2","title":"繞流介面","titleEn":"Bypass interfaces","text":"接合或密封也屬屏障的一部分，不能只檢查膜材料。","textEn":"Joints and seals are part of the barrier, not just the membrane material."}],"quiz":{"options":["產量有證據，屏障完整性尚未驗證","產量正常已足以證明完整性","可直接視為所有污染物都不存在"],"optionsEn":["Production evidenced; barrier integrity unverified","Normal production proves integrity","All contaminants can be considered absent"],"answer":0,"question":"流量正常但完整性證據不明，應如何分類？","questionEn":"Flow is normal but integrity evidence is unclear. How should the result be classified?","explanation":"功能宣稱需要對應證據，產量不能替代完整性。","explanationEn":"Functional claims need matching evidence; output quantity cannot substitute for integrity."}}],"title":"回用水邊界與前處理","titleEn":"Reuse boundaries and pretreatment","description":"辨認進流水、不同污染物與第一道膜屏障的證據。","descriptionEn":"Identify feedwater, contaminant classes and evidence for the first membrane barrier."},{"id":"b401-stage02","order":2,"steps":[{"id":"b401-v6-05","sequence":5,"order":1,"sourceIds":["v6-newater-process"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-04"],"title":"閉合RO三股水的物料平衡","titleEn":"Balance the three RO streams","objective":"區分進水、透過水與濃縮水的數量。","objectiveEn":"Distinguish feed, permeate and concentrate quantities.","instruction":"用自設且標明假想的單位流量，畫進水分成透過水和濃縮水。先檢查水量加總，再比較溶質去向，不把濃縮水當作消失或無污染的水。","instructionEn":"Use explicitly invented unit flows to split feed into permeate and concentrate. Check the water balance, then trace solutes without treating concentrate as vanished or contaminant-free.","observation":"觀察透過水比例提高時，濃縮側需要重新檢查哪些假設。","observationEn":"Consider which concentrate-side assumptions need review as the permeate fraction rises.","failure":"只報告產水量，遺漏濃縮水量及所攜帶的物質。","failureEn":"Reporting product flow without concentrate flow or transported substances.","check":"水量收支閉合，並標記尚未納入的溶質與實際設備限制。","checkEn":"Close the water balance and identify unmodeled solutes and actual equipment limits.","knowledge":[{"id":"b401-v6-05-k1","title":"分離不是消滅","titleEn":"Separation is not destruction","text":"膜分離改變物質分配，並不使被排除的物質憑空消失。","textEn":"Membrane separation redistributes substances rather than making rejected material disappear."},{"id":"b401-v6-05-k2","title":"比例與條件","titleEn":"Fractions and conditions","text":"水量回收比例只描述部分績效，須與品質和濃縮側條件一起看。","textEn":"Water recovery describes only part of performance and must be considered with quality and concentrate conditions."}],"quiz":{"options":["75單位，因與產水相同","25單位","0單位，因被膜去除"],"optionsEn":["75 units, because it equals product flow","25 units","0 units, because the membrane removes it"],"answer":1,"question":"假想進水100單位、透過水75單位，在忽略蓄積下濃縮水多少？","questionEn":"For invented feed of 100 units and permeate of 75, with no storage, what is concentrate flow?","explanation":"水量守恆給出100−75＝25；這只是教學收支，未代表可用操作比例。","explanationEn":"Conservation gives 100−75=25; this teaching balance does not define an operating recovery."}},{"id":"b401-v6-06","sequence":6,"order":2,"sourceIds":["v6-newater-quality","v6-newater-parameters"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-05"],"title":"解讀導電度而不過度推論","titleEn":"Interpret conductivity without overclaiming","objective":"區分離子相關指標與完整水質。","objectiveEn":"Distinguish an ion-related indicator from complete water quality.","instruction":"閱讀PUB水質表的導電度、濁度和有機碳欄位，分開記下單位與描述性質。自設兩份導電度相近但其他欄位不同的示例，比較可以及不可以下的結論。","instructionEn":"Read conductivity, turbidity and organic-carbon fields in PUB’s table, recording units and properties separately. Invent two samples with similar conductivity but differing other fields and compare valid and invalid conclusions.","observation":"注意單一低讀值不能補出未測項目。","observationEn":"A single low reading cannot supply unmeasured parameters.","failure":"用低導電度直接證明無微生物或所有有機污染物。","failureEn":"Using low conductivity as proof of no microorganisms or all organic contaminants.","check":"為三個指標各寫出一項能回答與不能回答的問題。","checkEn":"For each indicator, state one question it can and cannot answer.","knowledge":[{"id":"b401-v6-06-k1","title":"代理指標","titleEn":"Proxy indicators","text":"導電度反映水中導電性成分的綜合影響，不是每種污染物的直接濃度。","textEn":"Conductivity reflects combined conductive constituents, not direct concentration of every contaminant."},{"id":"b401-v6-06-k2","title":"單位語意","titleEn":"Meaning of units","text":"不同量測單位代表不同性質，不能因數字小就彼此比較優劣。","textEn":"Different units describe different properties; small numbers cannot be compared indiscriminately."}],"quiz":{"options":["低導電度證明微生物為零","可把導電度單位換成菌落數","離子相關指標已有資料，微生物狀態仍待驗證"],"optionsEn":["Low conductivity proves zero microorganisms","Conductivity units can be relabeled as colony counts","Ion-related evidence exists; microbial status remains unverified"],"answer":2,"question":"導電度很低而微生物結果尚未取得，最合理的結論是什麼？","questionEn":"Conductivity is low but microbiological results are unavailable. What follows?","explanation":"不同指標不能互相替代，尤其不能把物理電性當成微生物檢驗。","explanationEn":"Indicators are not interchangeable, particularly electrical properties and microbial testing."}},{"id":"b401-v6-07","sequence":7,"order":3,"sourceIds":["v6-newater-process","v6-newater-quality"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-06"],"title":"診斷膜效能趨勢","titleEn":"Diagnose membrane-performance trends","objective":"在比較膜效能前檢查進水與量測條件。","objectiveEn":"Check feed and measurement conditions before comparing membrane performance.","instruction":"自行建立兩段時間的流量、壓差、溫度與進水品質示例。先標記條件差異，再為產水下降列出積垢、進水變化與儀器偏差等假說，不指定清洗藥劑。","instructionEn":"Create example flow, differential pressure, temperature and feed-quality records for two periods. Mark condition changes before considering fouling, changed feed or instrument bias for lower output; prescribe no cleaning chemicals.","observation":"比較是否在相近條件下仍有持續偏差。","observationEn":"Check whether persistent differences remain under comparable conditions.","failure":"只用產量降低就斷定膜已損壞，忽略溫度、進水與量測。","failureEn":"Declaring membrane damage from lower output alone while ignoring temperature, feed and measurements.","check":"至少保留三種原因與一項可區分它們的補充資料。","checkEn":"Retain three candidate causes and a discriminating additional observation.","knowledge":[{"id":"b401-v6-07-k1","title":"條件化趨勢","titleEn":"Condition-aware trends","text":"性能比較需保留進水與環境條件，避免把條件變化當設備退化。","textEn":"Performance comparisons require feed and environmental context to distinguish condition changes from deterioration."},{"id":"b401-v6-07-k2","title":"診斷而非猜測","titleEn":"Diagnosis rather than guessing","text":"同一現象可能有多因；查證計畫應讓假說可被反駁。","textEn":"One symptom can have multiple causes; investigation should make hypotheses testable."}],"quiz":{"options":["核對比較條件與量測，再評估設備趨勢","直接認定膜完整性破壞","刪除溫度資料以保持表格簡單"],"optionsEn":["Reconcile conditions and measurements before judging equipment trends","Immediately conclude loss of membrane integrity","Delete temperature to simplify the table"],"answer":0,"question":"兩次產水量不同，但進水溫度也不同，應先做什麼？","questionEn":"Product flow differs between periods with different feed temperatures. What comes first?","explanation":"先控制比較範圍，才能讓效能趨勢具有可解釋性。","explanationEn":"Establishing comparable conditions makes performance trends interpretable."}},{"id":"b401-v6-08","sequence":8,"order":4,"sourceIds":["v6-newater-process","v6-newater-quality"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-07"],"title":"辨認UV屏障與驗證量","titleEn":"Identify the UV barrier and its evidence","objective":"說明消毒與物質分離的不同任務。","objectiveEn":"Explain the different tasks of disinfection and separation.","instruction":"在RO後方加入UV功能方塊，分別記錄光源狀態、水流與水的透光相關證據。畫出「燈亮但驗證不完整」情境，不自行提供飲用水消毒劑量。","instructionEn":"Add a UV block after RO, separating light-source state, flow and transmission-related evidence. Illustrate a lamp-on-but-unverified case without specifying drinking-water disinfection doses.","observation":"觀察光源通電是否能直接證明所有水得到足夠作用。","observationEn":"Ask whether an energized source proves adequate treatment of all passing water.","failure":"把燈亮等同消毒已驗證，或認為UV會把溶解鹽類分走。","failureEn":"Equating a lit lamp with verified disinfection or assuming UV separates dissolved salts.","check":"用不同證據欄位分開設備狀態、處理條件與水質驗證。","checkEn":"Separate equipment state, treatment conditions and quality verification in the record.","knowledge":[{"id":"b401-v6-08-k1","title":"功能差異","titleEn":"Functional difference","text":"UV作用於微生物失活；它不是RO式的溶質分流。","textEn":"UV targets microbial inactivation rather than RO-like solute separation."},{"id":"b401-v6-08-k2","title":"完整作用條件","titleEn":"Complete treatment conditions","text":"光源、流動與水的光學條件共同影響處理，不能只看開關。","textEn":"Source, flow and optical conditions jointly affect treatment; an on/off signal is insufficient."}],"quiz":{"options":["出水所有化學成分均已去除","設備有開啟指示，處理效果仍需對應證據","全部水質項目已通過檢驗"],"optionsEn":["Every chemical constituent has been removed","An on indication exists; treatment performance still needs evidence","All water-quality parameters have passed"],"answer":1,"question":"UV燈顯示開啟，可直接證明哪項？","questionEn":"A UV lamp indicates on. What does that directly prove?","explanation":"設備狀態不是完整水質結果，必須保留各自的驗證。","explanationEn":"Equipment state is not a complete quality result; each requires its own verification."}}],"title":"分離、診斷與消毒","titleEn":"Separation, diagnosis and disinfection","description":"把逆滲透的水量與水質、膜狀態及UV功能分開判讀。","descriptionEn":"Interpret RO flow and quality, membrane condition and UV function separately."},{"id":"b401-stage03","order":3,"steps":[{"id":"b401-v6-09","sequence":9,"order":1,"sourceIds":["v6-newater-quality","v6-newater-parameters"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-08"],"title":"建立採樣追溯鏈","titleEn":"Establish sample traceability","objective":"讓結果對應到正確位置、時間與樣品。","objectiveEn":"Link results to the correct location, time and sample.","instruction":"設計樣品表單，包含編號、取樣位置、時間、分析項目、方法和結果狀態。用兩個假想相近編號，演練如何辨認進水樣被誤標為出水樣。","instructionEn":"Design a sample form with ID, location, time, analyte, method and result state. Use two similar invented IDs to detect feedwater mislabeled as product.","observation":"檢查只有檢驗數字、沒有樣品身分時是否仍能解讀。","observationEn":"Assess whether a result remains interpretable without sample identity.","failure":"將不同時間、位置或方法的結果拼成同一批水的證明。","failureEn":"Combining results from different times, locations or methods as proof about one water batch.","check":"每筆示例結果可反查完整身分，錯置樣品須保留更正紀錄。","checkEn":"Trace each example result to its identity and retain correction records for mislabeling.","knowledge":[{"id":"b401-v6-09-k1","title":"代表性","titleEn":"Representativeness","text":"樣品能代表的水流與時間範圍，取決於採樣設計及紀錄。","textEn":"The stream and time represented by a sample depend on sampling design and records."},{"id":"b401-v6-09-k2","title":"結果狀態","titleEn":"Result status","text":"待分析、低於檢出能力及未檢測是不同狀態，不應都填成零。","textEn":"Pending, below detection capability and not tested are different states and should not all become zero."}],"quiz":{"options":["0，表示沒有檢出","以另一位置的結果自動補入","未檢測，保留待取得證據"],"optionsEn":["Zero, meaning not detected","Automatically fill with a result from another location","Not tested; evidence pending"],"answer":2,"question":"某項分析尚未執行，表格應怎麼填？","questionEn":"How should an analysis that has not been performed be recorded?","explanation":"未檢測並不等於未檢出；誠實的狀態是追溯鏈的一部分。","explanationEn":"Not tested is not equivalent to not detected; accurate status is part of traceability."}},{"id":"b401-v6-10","sequence":10,"order":2,"sourceIds":["v6-newater-process","v6-newater-parameters"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-09"],"title":"核對工業與間接回用介面","titleEn":"Review industrial and indirect-reuse interfaces","objective":"把目的地要求連到對應供水路徑。","objectiveEn":"Connect destination requirements to the appropriate supply route.","instruction":"建立兩欄：工業專管與水庫後接淨水場。為兩欄分別列交付點、後續處理與需確認的品質責任；不把工業廠內額外純化假定為PUB已完成。","instructionEn":"Compare dedicated industrial supply with reservoir-to-waterworks reuse. List handover point, further treatment and quality responsibility, without assuming PUB performs every customer’s additional purification.","observation":"觀察相同再生水來源在不同使用者端是否仍有不同後續需求。","observationEn":"The same reclaimed source may face different downstream needs at different users.","failure":"把NEWater典型值直接視為每一家工業製程的完整規格。","failureEn":"Treating NEWater typical values as complete specifications for every industrial process.","check":"兩條路徑各保留一項使用端需另行確認的介面條件。","checkEn":"Retain one destination-specific condition requiring separate confirmation for each route.","knowledge":[{"id":"b401-v6-10-k1","title":"適用途徑","titleEn":"Fit-for-purpose pathways","text":"水的目的地與後續處理會影響應驗證的介面，不能只看名稱。","textEn":"Destination and subsequent treatment influence the interface to verify, not just the water’s name."},{"id":"b401-v6-10-k2","title":"交付邊界","titleEn":"Handover boundary","text":"公用供水與客戶製程之間的品質責任須明確，不能隱含轉移。","textEn":"Quality responsibilities between utility supply and customer processes must be explicit."}],"quiz":{"options":["在客戶端增加明確的處理與驗證邊界","將供水典型值改成客戶所有需求","假定所有再生水用途完全相同"],"optionsEn":["Add an explicit customer treatment and verification boundary","Relabel typical supply values as all customer requirements","Assume every reuse application is identical"],"answer":0,"question":"某晶圓廠需要額外純化，合理的模型表示是什麼？","questionEn":"A wafer fab requires further purification. How should the model show it?","explanation":"上游供水與下游製程需求是不同邊界，需分開交代。","explanationEn":"Utility supply and downstream process needs are different boundaries that must be stated separately."}},{"id":"b401-v6-11","sequence":11,"order":3,"sourceIds":["v6-newater-quality","v6-newater-parameters"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-10"],"title":"記錄異常與未驗證狀態","titleEn":"Record anomalies and unverified states","objective":"避免在證據矛盾時給出過度的品質結論。","objectiveEn":"Avoid overclaiming quality when evidence conflicts.","instruction":"自行寫一個導電度趨勢改變但重測尚未完成的案例。列出感測器、取樣身分、進水條件與處理狀態的核對清單，交付狀態標成待驗證，不作真實放水指令。","instructionEn":"Invent a changed conductivity trend with repeat analysis pending. List sensor, sample identity, feed and treatment checks; label the learning handover unverified without issuing actual release commands.","observation":"注意一次正常重測是否足以解釋先前異常與整段時間。","observationEn":"Consider whether one normal repeat explains the prior anomaly and the entire affected period.","failure":"只留下正常讀值、刪除異常資料，造成虛假的連續合格紀錄。","failureEn":"Keeping normal readings while deleting anomalies to create a falsely continuous acceptable record.","check":"保留事件時間線、原始異常與待取得資料，結論不得超出觀察期間。","checkEn":"Preserve the timeline, original anomaly and missing evidence; limit conclusions to observed periods.","knowledge":[{"id":"b401-v6-11-k1","title":"偏差追查","titleEn":"Deviation investigation","text":"異常應有可追溯的查證與結案理由，不能只靠後續正常值覆蓋。","textEn":"Anomalies need traceable investigation and closure reasons rather than being overwritten by later normal values."},{"id":"b401-v6-11-k2","title":"時間範圍","titleEn":"Time scope","text":"採樣結果有其時間與位置範圍，不自動涵蓋未觀測時段。","textEn":"Sample results have time and location scope and do not automatically cover unobserved periods."}],"quiz":{"options":["直接刪除，僅保留最後結果","保留並查明適用範圍與原因","用兩次平均值宣告整段正常"],"optionsEn":["Delete it and retain only the latest result","Preserve it and investigate its scope and cause","Average the two and declare the entire interval normal"],"answer":1,"question":"後一次樣品正常，先前異常應如何處理？","questionEn":"A later sample is normal. What should happen to the earlier anomaly?","explanation":"後續結果不會自動解釋前次異常或填補時間空白。","explanationEn":"A later result does not automatically explain an earlier anomaly or fill a time gap."}},{"id":"b401-v6-12","sequence":12,"order":4,"sourceIds":["v6-newater-process","v6-newater-quality","v6-newater-parameters"],"simulationOnly":true,"estimatedMinutes":20,"prerequisiteIds":["b401-v6-11"],"title":"交付多重屏障品質卷宗","titleEn":"Deliver the multiple-barrier quality dossier","objective":"區分典型資料、操作準則與產品驗證證據。","objectiveEn":"Distinguish typical data, operating criteria and product-verification evidence.","instruction":"整理流程、物料平衡、屏障狀態、採樣紀錄與目的地介面。閱讀PUB典型值表的欄名及日期，為每個課程結論標上来源或自設假設，不把典型值轉成自行放行標準。","instructionEn":"Organize process, balance, barrier, sampling and destination records. Read the headings and date of PUB’s typical-values table; label sources or invented assumptions without converting typical values into self-authorized release criteria.","observation":"核對「典型」「指引」「本次實測」是否在文件中被混用。","observationEn":"Check whether typical, guideline and current measurement are being conflated.","failure":"拿公開典型值表代替當批水的實測與完整驗證。","failureEn":"Substituting a public typical-values table for measurements and verification of a specific batch.","check":"交付三類資料的區分表及至少四項可追溯證據，明示這不是飲水安全認證。","checkEn":"Submit a distinction table and at least four traceable evidence items, explicitly identifying this as no drinking-water safety certification.","knowledge":[{"id":"b401-v6-12-k1","title":"資料類別","titleEn":"Data categories","text":"典型值描述通常表現；指引、操作判準與特定樣品結果有不同角色。","textEn":"Typical values describe usual performance; guidelines, operating criteria and sample results have distinct roles."},{"id":"b401-v6-12-k2","title":"多重證據","titleEn":"Multiple evidence layers","text":"屏障、監測、採樣與目的地需求需相互吻合，單一指標無法概括。","textEn":"Barriers, monitoring, sampling and destination requirements must agree; one indicator cannot represent them all."}],"quiz":{"options":["使用者自行處理的水已通過全部驗證","任何實廠都可照表自行設定放行門檻","官方描述的通常水質表現與資料範圍"],"optionsEn":["User-treated water has passed all verification","Every plant may adopt the table as release settings","The authority’s described usual quality and data scope"],"answer":2,"question":"一張標示「典型值」的官方表格能直接證明哪件事？","questionEn":"What does an official table labeled typical values directly establish?","explanation":"公開典型資料是背景證據，不是特定樣品、設備或操作授權。","explanationEn":"Public typical data is background evidence, not verification or authorization for a particular sample, device or operation."}}],"title":"採樣、用途與品質交付","titleEn":"Sampling, uses and quality handover","description":"將追溯、異常處置概念及目的地要求連成驗證鏈。","descriptionEn":"Connect traceability, anomaly-handling concepts and destination requirements into an evidence chain."}],"title":"新加坡新生水系統","titleEn":"Singapore NEWater System","summary":"以多重處理屏障、物料平衡與水質證據，理解再生水如何連接城市與工業用水。","summaryEn":"Understand how reclaimed water links cities and industry through multiple treatment barriers, mass balance and water-quality evidence.","scope":"以公開資料建立的原創教學分解；所有步驟為紙上、數位模型與證據判讀練習。自繪的示意與自設資料必須標示假設；本站未提供現地工程資料，亦不是核准施工、設備操作或水質放行程序。","scopeEn":"Original educational decomposition of public information. Every step is a paper, digital-model or evidence-interpretation exercise. Label assumptions in self-drawn diagrams and invented data; this site does not supply field engineering records or approved construction, operating or water-release procedures.","diagram":{"type":"water-treatment","labels":["已處理用水","MF/UF","逆滲透","紫外線","用途與驗證"],"labelsEn":["Treated used water","MF/UF","Reverse osmosis","Ultraviolet","Use and verification"],"original":true,"notToScale":true},"stepCount":12,"estimatedMinutes":240,"curriculumVersion":6}};
